# --- 거부 이벤트를 받는다 ---

@Component
public class AuthorizationEventListener {
    @EventListener
    public void onDenied(AuthorizationDeniedEvent<?> event) {
        System.out.println(">>> DENIED user="
                + event.getAuthentication().get().getName()
                + " object=" + describe(event.getObject()));
    }

    private String describe(Object o) {
        if (o instanceof HttpServletRequest r) {
            return r.getMethod() + " " + r.getRequestURI();
        }
        if (o instanceof MethodInvocation m) {
            return m.getMethod().getDeclaringClass().getSimpleName()
                    + "." + m.getMethod().getName();
        }
        return String.valueOf(o);
    }
}

